import socket

class RedisError(Exception):
    pass

class RC:
    """Minimal raw RESP2 client with pipelining."""
    def __init__(self, host='127.0.0.1', port=6379, db=0):
        self.s = socket.create_connection((host, port))
        self.f = self.s.makefile('rb')
        self.db = db
        if db:
            r = self.cmd('SELECT', db)
            assert r == b'OK', r

    def _read(self):
        l = self.f.readline()
        if not l:
            raise RedisError('connection closed')
        l = l[:-2]
        t, rest = l[:1], l[1:]
        if t in (b'+', b':'):
            return rest if t == b'+' else int(rest)
        if t == b'-':
            raise RedisError(rest.decode('utf-8', 'replace'))
        if t == b'$':
            n = int(rest)
            if n == -1:
                return None
            return self.f.read(n + 2)[:-2]
        if t == b'*':
            n = int(rest)
            if n == -1:
                return None
            return [self._read() for _ in range(n)]
        if t == b'_':
            return None
        if t == b'%':
            n = int(rest)
            out = {}
            for _ in range(n):
                k = self._read(); v = self._read(); out[k] = v
            return out
        if t == b'#':
            return rest == b't'
        if t == b',':
            return float(rest)
        if t == b'(':
            return int(rest)
        if t == b'>':
            n = int(rest)
            return [self._read() for _ in range(n)]
        if t == b'~':
            n = int(rest)
            return [self._read() for _ in range(n)]
        raise RedisError('unknown resp type %r' % l)

    def cmd(self, *args):
        return self.pipeline([args])[0]

    def pipeline(self, cmds):
        buf = bytearray()
        for c in cmds:
            buf += b'*%d\r\n' % len(c)
            for a in c:
                if isinstance(a, str):
                    a = a.encode()
                buf += b'$%d\r\n%s\r\n' % (len(a), a)
        self.s.sendall(bytes(buf))
        return [self._read() for _ in cmds]

    def scan(self, pattern='*', count=500):
        cur = b'0'
        while True:
            cur, keys = self.cmd('SCAN', cur, 'COUNT', 1000, 'MATCH', pattern)
            for k in keys:
                yield k
            if cur == b'0':
                break

    def close(self):
        try: self.s.close()
        except Exception: pass
