#!/usr/bin/env python3
"""Migrate Redis 8.10 -> Valkey 9.1 with exact state reproduction.

Phase 1: snapshot source (logical, binary-safe) -> /tmp/snapshot.pkl
Phase 2: load into target (data, key TTLs via PEXPIREAT, hash field TTLs via
         HPEXPIREAT, streams incl. consumer groups/PEL/consumers)
Phase 3: verify target against a FRESH read of source
"""
import sys, pickle, time
sys.path.insert(0, '/tmp')
from rc import RC

SRC = dict(host='127.0.0.1', port=6379)
DST = dict(host='127.0.0.1', port=6380)
DBS = [0, 2]
BATCH = 400

def batches(seq, n=BATCH):
    buf = []
    for x in seq:
        buf.append(x)
        if len(buf) >= n:
            yield buf
            buf = []
    if buf:
        yield buf

# ---------------------------------------------------------------- phase 1
def snapshot():
    snap = {'when': time.time(), 'src_time': None, 'dbs': {}}
    for db in DBS:
        r = RC(port=SRC['port'], db=db)
        snap['src_time'] = r.cmd('TIME')
        keys = list(r.scan('*'))
        types = {}
        res = r.pipeline([[b'TYPE', k] for k in keys])
        for k, t in zip(keys, res):
            types.setdefault(t.decode(), []).append(k)
        info = {'types': {t: len(v) for t, v in types.items()}, 'keys': {}}
        # absolute key expiries
        for kb in batches(keys):
            res = r.pipeline([[b'PEXPIRETIME', k] for k in kb])
            for k, pe in zip(kb, res):
                info['keys'][k] = {'type': None, 'pexpiretime': pe}
        for k, t in zip(keys, res if False else []):
            pass
        # fill types
        for t, ks in types.items():
            for k in ks:
                info['keys'][k]['type'] = t
        # values
        for t, ks in types.items():
            for kb in batches(ks):
                cmds, idx = [], []
                for k in kb:
                    kt = info['keys'][k]['type']
                    if kt == 'string':
                        cmds.append([b'GET', k])
                    elif kt == 'list':
                        cmds.append([b'LRANGE', k, b'0', b'-1'])
                    elif kt == 'set':
                        cmds.append([b'SMEMBERS', k])
                    elif kt == 'zset':
                        cmds.append([b'ZRANGE', k, b'0', b'-1', b'WITHSCORES'])
                    elif kt == 'hash':
                        cmds.append([b'HGETALL', k])
                    elif kt == 'stream':
                        cmds.append([b'XRANGE', k, b'-', b'+'])
                    else:
                        raise SystemExit('unknown type %r for %r' % (kt, k))
                out = r.pipeline(cmds)
                for k, v in zip(kb, out):
                    info['keys'][k]['value'] = v
        # hash field expiries (absolute unix ms)
        for h in types.get('hash', []):
            fields = list(info['keys'][h]['value'].keys())
            pe = r.pipeline([[b'HPEXPIRETIME', h, b'FIELDS', len(fields)] + fields])
            info['keys'][h]['field_pexpiretime'] = dict(zip(fields, pe[0]))
        # stream metadata + groups
        for s in types.get('stream', []):
            st = r.cmd('XINFO', 'STREAM', s, 'FULL', 'COUNT', 1000000)
            groups = []
            for g in st.get(b'groups', []):
                groups.append({
                    'name': g[b'name'],
                    'last-delivered-id': g[b'last-delivered-id'],
                    'entries-read': g.get(b'entries-read'),
                    'lag': g.get(b'lag'),
                    'pel-count': g[b'pel-count'],
                    'nacked-count': g.get(b'nacked-count'),
                    'pending': [[p[0], p[1], p[2], p[3]] for p in g.get(b'pending', [])],
                    'consumers': [{'name': c[b'name'],
                                   'seen-time': c.get(b'seen-time'),
                                   'active-time': c.get(b'active-time'),
                                   'pel-count': c[b'pel-count'],
                                   'pending': [[p[0], p[1], p[2]] for p in c.get(b'pending', [])]}
                                  for c in g.get(b'consumers', [])],
                })
            info['keys'][s]['stream_info'] = {
                'length': st[b'length'],
                'entries-added': st[b'entries-added'],
                'max-deleted-entry-id': st[b'max-deleted-entry-id'],
                'recorded-first-entry-id': st[b'recorded-first-entry-id'],
                'last-generated-id': st[b'last-generated-id'],
                'pids-tracked': st.get(b'pids-tracked'),
                'iids-tracked': st.get(b'iids-tracked'),
                'groups': groups,
            }
        r.close()
        snap['dbs'][db] = info
    with open('/tmp/snapshot.pkl', 'wb') as f:
        pickle.dump(snap, f)
    return snap

# ---------------------------------------------------------------- phase 2
def load(snap):
    loaded = {}
    for db in DBS:
        info = snap['dbs'][db]
        v = RC(port=DST['port'], db=db)
        assert v.cmd('DBSIZE') == 0, 'target db %d not empty' % db
        n = {'set': 0, 'fttl': 0, 'pel': 0, 'groups': 0, 'consumers': 0}
        # 1. data
        for kb in batches(list(info['keys'].keys())):
            cmds = []
            for k in kb:
                t = info['keys'][k]['type']
                val = info['keys'][k]['value']
                if t == 'string':
                    cmds.append([b'SET', k, val])
                elif t == 'list':
                    cmds.append([b'RPUSH', k] + val)
                elif t == 'set':
                    cmds.append([b'SADD', k] + val)
                elif t == 'zset':
                    c = [b'ZADD', k]
                    for i in range(0, len(val), 2):
                        c += [val[i + 1], val[i]]
                    cmds.append(c)
                elif t == 'hash':
                    c = [b'HSET', k]
                    for f, fv in val.items():
                        c += [f, fv]
                    cmds.append(c)
                elif t == 'stream':
                    c = [b'XADD', k]
                    for eid, fields in val:
                        c.append(eid)
                        for f, fv in fields.items():
                            c += [f, fv]
                    cmds.append(c)
            res = v.pipeline(cmds)
            for rr in res:
                if rr != b'OK':
                    raise SystemExit('write failed: %r' % (rr,))
            n['set'] += len(cmds)
        # 2. key TTLs (absolute) - before field TTLs for safety
        vol = [(k, v['pexpiretime']) for k, v in info['keys'].items()
               if isinstance(v['pexpiretime'], int) and v['pexpiretime'] > 0]
        for kb in batches(vol):
            res = v.pipeline([[b'PEXPIREAT', k, pe] for k, pe in kb])
            for rr in res:
                if rr != 1:
                    raise SystemExit('PEXPIREAT failed: %r' % (rr,))
            n['set'] += len(kb)
        # 3. hash field TTLs (absolute)
        for k, kd in info['keys'].items():
            if kd['type'] != 'hash':
                continue
            fe = [(f, t) for f, t in kd['field_pexpiretime'].items()
                  if isinstance(t, int) and t > 0]
            for fb in batches(fe):
                c = [b'HPEXPIREAT', k, b'FIELDS', len(fb)]
                for f, t in fb:
                    c += [f, t]
                rr = v.cmd(*c)
                cnt = sum(1 for x in rr if x == 1)
                if cnt != len(fb):
                    raise SystemExit('HPEXPIREAT mismatch %r vs %d' % (rr, len(fb)))
                n['fttl'] += len(fb)
        # 4. streams: groups, consumers, PEL
        for k, kd in info['keys'].items():
            if kd['type'] != 'stream':
                continue
            si = kd['stream_info']
            for g in si['groups']:
                if g['entries-read'] is None:
                    # null entries-read reproduced by XGROUP CREATE $ (er=null, lag=0)
                    rr = v.cmd(b'XGROUP', b'CREATE', k, g['name'], b'$')
                else:
                    rr = v.cmd(b'XGROUP', b'CREATE', k, g['name'],
                               g['last-delivered-id'], b'ENTRIESREAD', g['entries-read'])
                if rr != b'OK':
                    raise SystemExit('XGROUP CREATE failed: %r' % (rr,))
                n['groups'] += 1
                for c in g['consumers']:
                    rr = v.cmd(b'XGROUP', b'CREATECONSUMER', k, g['name'], c['name'])
                    if rr != 1:
                        raise SystemExit('CREATECONSUMER failed: %r' % (rr,))
                    n['consumers'] += 1
                # PEL: FORCE+JUSTID keeps delivery-count, TIME sets delivery timestamp
                pel = g['pending']
                for pb in batches(pel, 200):
                    res = v.pipeline([[b'XCLAIM', k, g['name'], p[1], b'0', p[0],
                                       b'FORCE', b'JUSTID', b'TIME', p[2]] for p in pb])
                    for rr, p in zip(res, pb):
                        if not (isinstance(rr, list) and rr and rr[0] == p[0]):
                            raise SystemExit('XCLAIM FORCE failed: %r' % (rr,))
                        n['pel'] += 1
        # sanity counters
        dbsize = v.cmd('DBSIZE')
        loaded[db] = (n, dbsize)
        v.close()
    return loaded

# ---------------------------------------------------------------- phase 3
def verify(snap):
    problems, notes = [], []
    max_ttl_delta = 0
    max_seen_delta = 0
    for db in DBS:
        s = RC(port=SRC['port'], db=db)
        t = RC(port=DST['port'], db=db)
        skeys = sorted(s.scan('*'))
        tkeys = sorted(t.scan('*'))
        if skeys != tkeys:
            only_s = set(map(bytes, skeys)) - set(map(bytes, tkeys))
            only_t = set(map(bytes, tkeys)) - set(map(bytes, skeys))
            problems.append('db%d keyset differs: only-src=%d only-dst=%d (e.g. %r / %r)'
                            % (db, len(only_s), len(only_t), list(only_s)[:3], list(only_t)[:3]))
            continue
        # types + absolute key expiry
        st = s.pipeline([[b'TYPE', k] for k in skeys])
        tt = t.pipeline([[b'TYPE', k] for k in skeys])
        for k, a, b in zip(skeys, st, tt):
            if a != b:
                problems.append('db%d %r type %r != %r' % (db, k, a, b))
        spe = s.pipeline([[b'PEXPIRETIME', k] for k in skeys])
        tpe = t.pipeline([[b'PEXPIRETIME', k] for k in skeys])
        for k, a, b in zip(skeys, spe, tpe):
            if a != b:
                delta = abs((a or 0) - (b or 0))
                max_ttl_delta = max(max_ttl_delta, delta)
                if delta > 5000:
                    problems.append('db%d %r pexpiretime %r != %r' % (db, k, a, b))
        # remaining ttl quick compare
        spt = s.pipeline([[b'PTTL', k] for k in skeys])
        tpt = t.pipeline([[b'PTTL', k] for k in skeys])
        for k, a, b in zip(skeys, spt, tpt):
            if (a < 0) != (b < 0) or (a >= 0 and b >= 0 and abs(a - b) > 5000):
                problems.append('db%d %r PTTL %r vs %r' % (db, k, a, b))
        # values
        for k in skeys:
            ty = s.cmd('TYPE', k)
            if ty == b'string':
                a, b = s.cmd('GET', k), t.cmd('GET', k)
                if a != b: problems.append('db%d string %r value differs' % (db, k))
            elif ty == b'list':
                a, b = s.cmd('LRANGE', k, 0, -1), t.cmd('LRANGE', k, 0, -1)
                if a != b: problems.append('db%d list %r value differs' % (db, k))
            elif ty == b'set':
                a, b = s.cmd('SMEMBERS', k), t.cmd('SMEMBERS', k)
                if sorted(a) != sorted(b): problems.append('db%d set %r value differs' % (db, k))
            elif ty == b'zset':
                a, b = s.cmd('ZRANGE', k, 0, -1, b'WITHSCORES'), t.cmd('ZRANGE', k, 0, -1, b'WITHSCORES')
                if a != b: problems.append('db%d zset %r value differs' % (db, k))
            elif ty == b'hash':
                a, b = s.cmd('HGETALL', k), t.cmd('HGETALL', k)
                if a != b: problems.append('db%d hash %r value differs' % (db, k))
                sf = list(a.keys())
                if sf:
                    af = s.pipeline([[b'HPEXPIRETIME', k, b'FIELDS', len(sf)] + sf])
                    bf = t.pipeline([[b'HPEXPIRETIME', k, b'FIELDS', len(sf)] + sf])
                    for f, x, y in zip(sf, af[0], bf[0]):
                        if x != y:
                            problems.append('db%d hash %r field %r expiry %r != %r' % (db, k, f, x, y))
            elif ty == b'stream':
                a, b = s.cmd('XRANGE', k, b'-', b'+'), t.cmd('XRANGE', k, b'-', b'+')
                if a != b: problems.append('db%d stream %r entries differ' % (db, k))
                si, ti = s.cmd('XINFO', 'STREAM', k, 'FULL', 'COUNT', 1000000), t.cmd('XINFO', 'STREAM', k, 'FULL', 'COUNT', 1000000)
                for fld in (b'length', b'entries-added', b'max-deleted-entry-id',
                            b'recorded-first-entry-id', b'last-generated-id'):
                    if si.get(fld) != ti.get(fld):
                        problems.append('db%d stream %r %s %r != %r' % (db, k, fld.decode(), si.get(fld), ti.get(fld)))
                sg = {g[b'name']: g for g in si.get(b'groups', [])}
                tg = {g[b'name']: g for g in ti.get(b'groups', [])}
                if set(sg) != set(tg):
                    problems.append('db%d stream %r group names differ %r vs %r' % (db, k, set(sg), set(tg)))
                    continue
                for name, g in sg.items():
                    h = tg[name]
                    for fld in (b'last-delivered-id', b'entries-read', b'lag', b'pel-count'):
                        if g.get(fld) != h.get(fld):
                            problems.append('db%d stream %r group %s %s %r != %r'
                                            % (db, k, name.decode(), fld.decode(), g.get(fld), h.get(fld)))
                    sp = [[p[0], p[1], p[3]] for p in g.get(b'pending', [])]
                    tp = [[p[0], p[1], p[3]] for p in h.get(b'pending', [])]
                    if sorted(sp) != sorted(tp):
                        problems.append('db%d stream %r group %s PEL differs\n  src=%r\n  dst=%r'
                                        % (db, k, name.decode(), sorted(sp)[:5], sorted(tp)[:5]))
                    # delivery timestamps (absolute) should match exactly
                    stimes = sorted(p[2] for p in g.get(b'pending', []))
                    ttimes = sorted(p[2] for p in h.get(b'pending', []))
                    if stimes != ttimes:
                        problems.append('db%d stream %r group %s delivery times differ %r vs %r'
                                        % (db, k, name.decode(), stimes[:3], ttimes[:3]))
                    sc = {c[b'name']: c for c in g.get(b'consumers', [])}
                    tc = {c[b'name']: c for c in h.get(b'consumers', [])}
                    if set(sc) != set(tc):
                        problems.append('db%d stream %r group %s consumer names differ %r vs %r'
                                        % (db, k, name.decode(), set(sc), set(tc)))
                    else:
                        for cn, c in sc.items():
                            d = tc[cn]
                            if c[b'pel-count'] != d[b'pel-count']:
                                problems.append('db%d stream %r group %s consumer %s pel-count %r != %r'
                                                % (db, k, name.decode(), cn.decode(), c[b'pel-count'], d[b'pel-count']))
                            if c.get(b'seen-time') and d.get(b'seen-time'):
                                max_seen_delta = max(max_seen_delta, abs(c[b'seen-time'] - d[b'seen-time']))
        n_src, n_dst = s.cmd('DBSIZE'), t.cmd('DBSIZE')
        if n_src != n_dst:
            problems.append('db%d DBSIZE %r != %r' % (db, n_src, n_dst))
        s.close(); t.close()
    return problems, notes, max_ttl_delta, max_seen_delta

if __name__ == '__main__':
    mode = sys.argv[1]
    if mode == 'snapshot':
        snap = snapshot()
        for db in DBS:
            i = snap['dbs'][db]
            nfttl = sum(1 for kd in i['keys'].values() if kd['type'] == 'hash'
                        for t in kd['field_pexpiretime'].values() if isinstance(t, int) and t > 0)
            nvol = sum(1 for kd in i['keys'].values() if isinstance(kd['pexpiretime'], int) and kd['pexpiretime'] > 0)
            idm = sum((kd.get('stream_info', {}).get('pids-tracked') or 0) + (kd.get('stream_info', {}).get('iids-tracked') or 0)
                      for kd in i['keys'].values() if kd['type'] == 'stream')
            print('db%d: %d keys %r, volatile=%d, field-ttl-fields=%d, idmp-tracked=%d'
                  % (db, len(i['keys']), i['types'], nvol, nfttl, idm))
        print('src TIME:', snap['src_time'])
    elif mode == 'load':
        snap = pickle.load(open('/tmp/snapshot.pkl', 'rb'))
        print('load:', load(snap))
    elif mode == 'verify':
        snap = pickle.load(open('/tmp/snapshot.pkl', 'rb'))
        p, nt, mtd, msd = verify(snap)
        print('max |pexpiretime delta| ms:', mtd)
        print('max |consumer seen-time delta| ms:', msd)
        if p:
            print('PROBLEMS (%d):' % len(p))
            for x in p[:40]:
                print(' -', x)
            sys.exit(1)
        print('VERIFICATION PASSED')
